```javascript
class ValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function parseAge(value) {
  const age = Number(value);
  if (!Number.isInteger(age) || age < 0) throw new ValidationError("Age must be a non-negative integer", "age");
  return age;
}
